using AegisCore.Contracts.Common.Interfaces;
using AegisCore.Domain;
using AegisCore.Domain.Entities;
using Microsoft.EntityFrameworkCore;

namespace AegisCore.Infrastructure.Repositories;

public class QueueDefinitionRepository : Repository<QueueDefinition>, IQueueDefinitionRepository { public QueueDefinitionRepository(AegisDbContext c) : base(c) { } public async Task<IReadOnlyList<QueueDefinition>> GetByStatusAsync(QueueStatus s, CancellationToken ct) => await _dbSet.Where(q => q.Status == s).ToListAsync(ct); }
public class QueueJobRepository : Repository<QueueJob>, IQueueJobRepository { public QueueJobRepository(AegisDbContext c) : base(c) { } public async Task<IReadOnlyList<QueueJob>> GetByQueueAsync(Guid qId, CancellationToken ct) => await _dbSet.Where(j => j.QueueId == qId).ToListAsync(ct); public async Task<IReadOnlyList<QueueJob>> GetFailedAsync(CancellationToken ct) => await _dbSet.Where(j => j.Status == JobExecutionStatus.Failed).ToListAsync(ct); public async Task<IReadOnlyList<QueueJob>> GetDeadLetterAsync(CancellationToken ct) => await _dbSet.Where(j => j.AttemptCount >= 3 && j.Status == JobExecutionStatus.Failed).ToListAsync(ct); }
public class DomainEventRepository : Repository<DomainEvent>, IDomainEventRepository { public DomainEventRepository(AegisDbContext c) : base(c) { } public async Task<IReadOnlyList<DomainEvent>> GetByAggregateAsync(string aggId, CancellationToken ct) => await _dbSet.Where(e => e.AggregateId == aggId).OrderByDescending(e => e.OccurredAt).ToListAsync(ct); public async Task<IReadOnlyList<DomainEvent>> GetByCorrelationIdAsync(string cId, CancellationToken ct) => await _dbSet.Where(e => e.CorrelationId == cId).OrderBy(e => e.OccurredAt).ToListAsync(ct); public async Task<IReadOnlyList<DomainEvent>> GetFailedAsync(CancellationToken ct) => await _dbSet.Where(e => e.Status == EventStatus.Failed).ToListAsync(ct); }
public class EventSchemaVersionRepository : Repository<EventSchemaVersion>, IEventSchemaVersionRepository { public EventSchemaVersionRepository(AegisDbContext c) : base(c) { } public async Task<EventSchemaVersion?> GetByTypeAndVersionAsync(string type, int v, CancellationToken ct) => await _dbSet.FirstOrDefaultAsync(s => s.EventType == type && s.Version == v, ct); }
public class DiagnosticFindingRepository : Repository<DiagnosticFinding>, IDiagnosticFindingRepository { public DiagnosticFindingRepository(AegisDbContext c) : base(c) { } public async Task<IReadOnlyList<DiagnosticFinding>> GetByCategoryAsync(string cat, CancellationToken ct) => await _dbSet.Where(f => f.Category == cat).ToListAsync(ct); }
public class SlowQueryRepository : Repository<SlowQuery>, ISlowQueryRepository { public SlowQueryRepository(AegisDbContext c) : base(c) { } public async Task<IReadOnlyList<SlowQuery>> GetRecentAsync(int limit, CancellationToken ct) => await _dbSet.OrderByDescending(q => q.RecordedAt).Take(limit).ToListAsync(ct); }
public class ServiceRegistrationRepository : Repository<ServiceRegistration>, IServiceRegistrationRepository { public ServiceRegistrationRepository(AegisDbContext c) : base(c) { } public async Task<IReadOnlyList<ServiceRegistration>> GetByStatusAsync(ServiceStatus s, CancellationToken ct) => await _dbSet.Where(r => r.Status == s).ToListAsync(ct); }
public class ApiEndpointRepository : Repository<ApiEndpoint>, IApiEndpointRepository { public ApiEndpointRepository(AegisDbContext c) : base(c) { } public async Task<IReadOnlyList<ApiEndpoint>> GetByModuleAsync(string m, CancellationToken ct) => await _dbSet.Where(e => e.Module == m).ToListAsync(ct); }
public class HealthScoreRepository : Repository<HealthScore>, IHealthScoreRepository { public HealthScoreRepository(AegisDbContext c) : base(c) { } public async Task<HealthScore?> GetLatestAsync(CancellationToken ct) => await _dbSet.OrderByDescending(s => s.GeneratedAt).FirstOrDefaultAsync(ct); public async Task<IReadOnlyList<HealthScore>> GetHistoryAsync(int limit, CancellationToken ct) => await _dbSet.OrderByDescending(s => s.GeneratedAt).Take(limit).ToListAsync(ct); }
public class IntegrationRegistrationRepository : Repository<IntegrationRegistration>, IIntegrationRegistrationRepository { public IntegrationRegistrationRepository(AegisDbContext c) : base(c) { } public async Task<IReadOnlyList<IntegrationRegistration>> GetByTypeAsync(IntegrationType t, CancellationToken ct) => await _dbSet.Where(i => i.Type == t).ToListAsync(ct); public async Task<IReadOnlyList<IntegrationRegistration>> GetFailingAsync(CancellationToken ct) => await _dbSet.Where(i => i.Status == IntegrationStatus.Down).ToListAsync(ct); }
public class BenchmarkRunRepository : Repository<BenchmarkRun>, IBenchmarkRunRepository { public BenchmarkRunRepository(AegisDbContext c) : base(c) { } public async Task<IReadOnlyList<BenchmarkRun>> GetRecentAsync(int limit, CancellationToken ct) => await _dbSet.OrderByDescending(r => r.StartedAt).Take(limit).ToListAsync(ct); }
public class AIProviderRepository : Repository<AIProvider>, IAIProviderRepository { public AIProviderRepository(AegisDbContext c) : base(c) { } public async Task<IReadOnlyList<AIProvider>> GetActiveAsync(CancellationToken ct) => await _dbSet.Where(p => p.IsActive).ToListAsync(ct); }
public class AIModelRepository : Repository<AIModel>, IAIModelRepository { public AIModelRepository(AegisDbContext c) : base(c) { } public async Task<IReadOnlyList<AIModel>> GetByProviderAsync(Guid pId, CancellationToken ct) => await _dbSet.Where(m => m.ProviderId == pId).ToListAsync(ct); }
public class AITokenUsageRepository : Repository<AITokenUsage>, IAITokenUsageRepository { public AITokenUsageRepository(AegisDbContext c) : base(c) { } public async Task<IReadOnlyList<AITokenUsage>> GetByDomainAsync(string d, DateTime? from, DateTime? to, CancellationToken ct) { var q = _dbSet.Where(u => u.Domain == d); if (from.HasValue) q = q.Where(u => u.RecordedAt >= from.Value); if (to.HasValue) q = q.Where(u => u.RecordedAt <= to.Value); return await q.ToListAsync(ct); } public async Task<long> GetTotalTokensAsync(string d, DateTime? from, DateTime? to, CancellationToken ct) { var usages = await GetByDomainAsync(d, from, to, ct); return usages.Sum(u => (long)u.InputTokens + u.OutputTokens); } }
public class PromptRepository : Repository<Prompt>, IPromptRepository { public PromptRepository(AegisDbContext c) : base(c) { } public async Task<IReadOnlyList<Prompt>> GetByDomainAsync(string d, CancellationToken ct) => await _dbSet.Where(p => p.Domain == d).ToListAsync(ct); public async Task<Prompt?> GetByNameAsync(string n, CancellationToken ct) => await _dbSet.FirstOrDefaultAsync(p => p.Name == n, ct); public async Task<Prompt?> GetActiveByDomainAsync(string d, CancellationToken ct) => await _dbSet.FirstOrDefaultAsync(p => p.Domain == d && p.ApprovalStatus == PromptApprovalStatus.Active, ct); }
public class PromptVersionRepository : Repository<PromptVersion>, IPromptVersionRepository { public PromptVersionRepository(AegisDbContext c) : base(c) { } public async Task<IReadOnlyList<PromptVersion>> GetByPromptAsync(Guid pId, CancellationToken ct) => await _dbSet.Where(v => v.PromptId == pId).OrderByDescending(v => v.VersionNumber).ToListAsync(ct); }
public class GuardrailRuleRepository : Repository<GuardrailRule>, IGuardrailRuleRepository { public GuardrailRuleRepository(AegisDbContext c) : base(c) { } public async Task<IReadOnlyList<GuardrailRule>> GetActiveAsync(CancellationToken ct) => await _dbSet.Where(r => r.IsActive).ToListAsync(ct); }
public class GuardrailViolationRepository : Repository<GuardrailViolation>, IGuardrailViolationRepository { public GuardrailViolationRepository(AegisDbContext c) : base(c) { } public async Task<IReadOnlyList<GuardrailViolation>> GetRecentAsync(int limit, CancellationToken ct) => await _dbSet.OrderByDescending(v => v.OccurredAt).Take(limit).ToListAsync(ct); }
public class AIFeedbackRepository : Repository<AIFeedback>, IAIFeedbackRepository { public AIFeedbackRepository(AegisDbContext c) : base(c) { } public async Task<IReadOnlyList<AIFeedback>> GetByDomainAsync(string d, CancellationToken ct) => await _dbSet.Where(f => f.Domain == d).ToListAsync(ct); }
public class LicenseRepository : Repository<License>, ILicenseRepository { public LicenseRepository(AegisDbContext c) : base(c) { } public async Task<License?> GetByKeyAsync(string key, CancellationToken ct) => await _dbSet.FirstOrDefaultAsync(l => l.LicenseKey == key, ct); public async Task<IReadOnlyList<License>> GetByStatusAsync(LicenseStatus s, CancellationToken ct) => await _dbSet.Where(l => l.Status == s).ToListAsync(ct); }
public class SupportTicketRepository : Repository<SupportTicket>, ISupportTicketRepository { public SupportTicketRepository(AegisDbContext c) : base(c) { } public async Task<IReadOnlyList<SupportTicket>> GetByCustomerAsync(Guid cId, CancellationToken ct) => await _dbSet.Where(t => t.CustomerId == cId).ToListAsync(ct); }
public class UpdateDeploymentRepository : Repository<UpdateDeployment>, IUpdateDeploymentRepository { public UpdateDeploymentRepository(AegisDbContext c) : base(c) { } public async Task<IReadOnlyList<UpdateDeployment>> GetRecentAsync(int limit, CancellationToken ct) => await _dbSet.OrderByDescending(d => d.StartedAt).Take(limit).ToListAsync(ct); }
public class OfficialModuleRepository : Repository<OfficialModule>, IOfficialModuleRepository { public OfficialModuleRepository(AegisDbContext c) : base(c) { } public async Task<IReadOnlyList<OfficialModule>> GetPublishedAsync(CancellationToken ct) => await _dbSet.Where(m => m.IsPublished).ToListAsync(ct); }
public class FeeDefaulterRepository : Repository<FeeDefaulterRecord>, IFeeDefaulterRepository { public FeeDefaulterRepository(AegisDbContext c) : base(c) { } public async Task<IReadOnlyList<FeeDefaulterRecord>> GetByStudentAsync(Guid sId, CancellationToken ct) => await _dbSet.Where(f => f.StudentId == sId).ToListAsync(ct); public async Task<IReadOnlyList<FeeDefaulterRecord>> GetPendingAsync(CancellationToken ct) => await _dbSet.Where(f => f.Status != DefaulterStatus.Cleared).ToListAsync(ct); }
public class MisconductCaseRepository : Repository<MisconductCase>, IMisconductCaseRepository { public MisconductCaseRepository(AegisDbContext c) : base(c) { } public async Task<IReadOnlyList<MisconductCase>> GetByStudentAsync(Guid sId, CancellationToken ct) => await _dbSet.Where(m => m.StudentId == sId).ToListAsync(ct); public async Task<IReadOnlyList<MisconductCase>> GetByStatusAsync(MisconductStatus s, CancellationToken ct) => await _dbSet.Where(m => m.Status == s).ToListAsync(ct); }
public class FacultyWorkloadRepository : Repository<FacultyWorkload>, IFacultyWorkloadRepository { public FacultyWorkloadRepository(AegisDbContext c) : base(c) { } public async Task<IReadOnlyList<FacultyWorkload>> GetByFacultyAsync(Guid fId, CancellationToken ct) => await _dbSet.Where(w => w.FacultyId == fId).ToListAsync(ct); }
public class DegreeVerificationRepository : Repository<DegreeVerification>, IDegreeVerificationRepository { public DegreeVerificationRepository(AegisDbContext c) : base(c) { } public async Task<DegreeVerification?> GetByTokenAsync(string token, CancellationToken ct) => await _dbSet.FirstOrDefaultAsync(v => v.VerificationToken == token, ct); }
public class RegistrationWindowRepository : Repository<RegistrationWindow>, IRegistrationWindowRepository { public RegistrationWindowRepository(AegisDbContext c) : base(c) { } public async Task<RegistrationWindow?> GetActiveAsync(CancellationToken ct) => await _dbSet.FirstOrDefaultAsync(w => w.Status == RegistrationStatus.Open && DateTime.UtcNow >= w.OpensAt && DateTime.UtcNow <= w.ClosesAt, ct); }
public class RegistrationEnrollmentRepository : Repository<RegistrationEnrollment>, IRegistrationEnrollmentRepository { public RegistrationEnrollmentRepository(AegisDbContext c) : base(c) { } public async Task<IReadOnlyList<RegistrationEnrollment>> GetByStudentAsync(Guid sId, CancellationToken ct) => await _dbSet.Where(e => e.StudentId == sId).ToListAsync(ct); public async Task<IReadOnlyList<RegistrationEnrollment>> GetByWindowAsync(Guid wId, CancellationToken ct) => await _dbSet.Where(e => e.WindowId == wId).ToListAsync(ct); }
public class CurriculumProposalRepository : Repository<CurriculumProposal>, ICurriculumProposalRepository { public CurriculumProposalRepository(AegisDbContext c) : base(c) { } public async Task<IReadOnlyList<CurriculumProposal>> GetByStatusAsync(CurriculumApprovalStatus s, CancellationToken ct) => await _dbSet.Where(p => p.Status == s).ToListAsync(ct); }
public class AccessAuditLogRepository : Repository<AccessAuditLog>, IAccessAuditLogRepository { public AccessAuditLogRepository(AegisDbContext c) : base(c) { } public async Task<IReadOnlyList<AccessAuditLog>> GetBlockedAsync(CancellationToken ct) => await _dbSet.Where(l => l.IsBlocked).OrderByDescending(l => l.RecordedAt).ToListAsync(ct); }
public class HardcodingFindingRepository : Repository<HardcodingFinding>, IHardcodingFindingRepository { public HardcodingFindingRepository(AegisDbContext c) : base(c) { } public async Task<IReadOnlyList<HardcodingFinding>> GetBySeverityAsync(HardcodingSeverity s, CancellationToken ct) => await _dbSet.Where(f => f.Severity == s).ToListAsync(ct); public async Task<IReadOnlyList<HardcodingFinding>> GetUnresolvedAsync(CancellationToken ct) => await _dbSet.Where(f => !f.IsResolved).ToListAsync(ct); }
